window.UAWF_SEARCH=[{"t":"Built by farmers, for farmers.","p":"About","u":"about/","x":"UAWF SACCO is a member-owned savings and credit cooperative for farmers, livestock keepers and agricultural workers around Mbarara City, registered under the Cooperative Societies Act, Cap 107.","k":"page"},{"t":"Why we came together","p":"About","u":"about/#story","x":"Farming income does not arrive every month. It comes at harvest, and it has to last until the next one. Most banks want a land title, a salary slip and months of paperwork before they lend a shilling. Many smallholder fa","k":"section"},{"t":"What we work towards","p":"About","u":"about/#mission","x":"To mobilise savings and provide affordable credit and training that suit farming and raise the incomes of farmers and agricultural workers.","k":"section"},{"t":"Our mission","p":"About","u":"about/#mission","x":"To mobilise savings and provide affordable credit and training that suit farming and raise the incomes of farmers and agricultural workers.","k":"item"},{"t":"Our vision","p":"About","u":"about/#mission","x":"A thriving farming community in Western Uganda where every member is financially secure and able to invest in their land and family.","k":"item"},{"t":"What we stand for","p":"About","u":"about/#mission","x":"Mission & vision To mobilise savings and provide affordable credit and training that suit farming and raise the incomes of farmers and agricultural workers. A thriving farming community in Western Uganda where every member is financially secure and able to invest in their land and family. Honesty We","k":"item"},{"t":"Honesty","p":"About","u":"about/#mission","x":"We keep clear, truthful records of every shilling saved and borrowed.","k":"item"},{"t":"One member, one vote","p":"About","u":"about/#mission","x":"Whether you save a little or a lot, your voice counts the same at our meetings.","k":"item"},{"t":"Loans that follow the season","p":"About","u":"about/#mission","x":"Repayment plans are built around planting and harvest, not a fixed office calendar.","k":"item"},{"t":"Transparency","p":"About","u":"about/#mission","x":"Rates, fees and decisions are explained in plain language, in the open.","k":"item"},{"t":"Community care","p":"About","u":"about/#mission","x":"We grow together, supporting members through good seasons and hard ones.","k":"item"},{"t":"How a SACCO works","p":"About","u":"about/#how-it-works","x":"A SACCO is owned by the people who use it. Here is how your savings turn into support for fellow members, and back to you.","k":"section"},{"t":"Members save","p":"About","u":"about/#how-it-works","x":"Each member buys shares and saves regularly, weekly or monthly, in amounts they can manage.","k":"item"},{"t":"Savings are pooled","p":"About","u":"about/#how-it-works","x":"All savings are kept together safely, with clear records reported at every general meeting.","k":"item"},{"t":"Members borrow","p":"About","u":"about/#how-it-works","x":"The pooled funds are lent to members at fair rates, with repayment plans that follow the farming season.","k":"item"},{"t":"Benefits are shared","p":"About","u":"about/#how-it-works","x":"Interest paid on loans stays in the SACCO. Any surplus benefits members, as agreed at the general meeting.","k":"item"},{"t":"For everyone who works the land","p":"About","u":"about/#who-we-serve","x":"We are built around farm life in and around Mbarara City, but membership is open to any Ugandan aged 18 and above.","k":"section"},{"t":"Smallholder farmers","p":"About","u":"about/#who-we-serve","x":"Crop farmers growing matooke, maize, beans, coffee and more.","k":"item"},{"t":"Livestock & dairy keepers","p":"About","u":"about/#who-we-serve","x":"Cattle, goat and poultry keepers building up their herds.","k":"item"},{"t":"Farm & plantation workers","p":"About","u":"about/#who-we-serve","x":"Workers on farms, plantations and dairies earning a wage.","k":"item"},{"t":"Agro processors & traders","p":"About","u":"about/#who-we-serve","x":"People who process, store and sell farm produce.","k":"item"},{"t":"Farmer groups","p":"About","u":"about/#who-we-serve","x":"Groups and associations that save and borrow together.","k":"item"},{"t":"Member rights & duties","p":"About","u":"about/#member-rights","x":"Being a member means being an owner. Here is what you can expect from the SACCO, and what the SACCO asks of you.","k":"section"},{"t":"Your rights","p":"About","u":"about/#member-rights","x":"Attend and vote at general meetings, one member one vote Stand for election to the board and committees Apply for loans according to the SACCO's loan policy Receive clear statements of your savings, shares and loans Inspect the SACCO's bylaws and annual reports Take part in member training","k":"item"},{"t":"Your duties","p":"About","u":"about/#member-rights","x":"Save regularly and hold the minimum number of shares Repay loans on time, as agreed in your repayment plan Follow the SACCO's bylaws and policies Attend general meetings and take part in decisions Guarantee fellow members responsibly Keep your contact and next of kin details up to date","k":"item"},{"t":"How the SACCO is led","p":"About","u":"about/#leadership","x":"Power sits with the members. Leaders are elected by members at the general meeting and are accountable to them.","k":"section"},{"t":"General Meeting of members","p":"About","u":"about/#leadership","x":"The highest authority. All members meet at least once a year to approve accounts, set policy and elect leaders.","k":"item"},{"t":"Board of Directors","p":"About","u":"about/#leadership","x":"Elected by members to set direction, approve policies and oversee management on the members' behalf.","k":"item"},{"t":"Supervisory Committee","p":"About","u":"about/#leadership","x":"Elected by members to check the books, review how the SACCO is run and report back at the general meeting.","k":"item"},{"t":"Credit Committee","p":"About","u":"about/#leadership","x":"Reviews loan applications fairly and in line with the loan policy approved by members.","k":"item"},{"t":"Management & staff","p":"About","u":"about/#leadership","x":"Run the office day to day: receiving savings, processing loans and keeping members' records.","k":"item"},{"t":"Legally registered, and supervised","p":"About","u":"about/#registration","x":"UAWF SACCO is registered under Section 6(1) of the Cooperative Societies Act, Cap 107, and is supervised by the Registrar of Cooperative Societies, Republic of Uganda.","k":"section"},{"t":"Where we are, and where we are going","p":"About","u":"about/#journey","x":"Farmers and agricultural workers around Mbarara meet and agree to form a savings and credit cooperative of their own.","k":"section"},{"t":"Farmers come together","p":"About","u":"about/#journey","x":"Farmers and agricultural workers around Mbarara meet and agree to form a savings and credit cooperative of their own.","k":"item"},{"t":"Registered by the Registrar","p":"About","u":"about/#journey","x":"UAWF SACCO receives certificate P.298866 under Section 6(1) of the Cooperative Societies Act, Cap 107.","k":"item"},{"t":"Probationary period","p":"About","u":"about/#journey","x":"We grow our membership, keep proper records and report openly, as the Registrar reviews how the society is run.","k":"item"},{"t":"Full registration","p":"About","u":"about/#journey","x":"Our goal: to move on to full registration and keep growing savings, credit and training for members.","k":"item"},{"t":"Plan your loan and your savings.","p":"Calculator","u":"calculator/","x":"See roughly what a loan could cost you each month, or how your savings could grow. All figures are in Ugandan Shillings (UGX).","k":"page"},{"t":"UGX 0","p":"Calculator","u":"calculator/#panel-loan","x":"These figures are examples only, to help you plan. Actual interest rates, fees and terms are set by the SACCO office and may change. Please visit us or call to confirm before you apply.","k":"item"},{"t":"What the numbers mean","p":"Calculator","u":"calculator/#tips","x":"The estimated amount you would pay each month. Your actual plan can follow your harvest, so talk to us if monthly payments do not suit you.","k":"section"},{"t":"Monthly repayment","p":"Calculator","u":"calculator/#tips","x":"The estimated amount you would pay each month. Your actual plan can follow your harvest, so talk to us if monthly payments do not suit you.","k":"item"},{"t":"Total interest","p":"Calculator","u":"calculator/#tips","x":"The cost of borrowing. A shorter repayment period usually means less interest in total, but higher payments each month.","k":"item"},{"t":"Save first, borrow later","p":"Calculator","u":"calculator/#tips","x":"Regular savings build the record that supports your loan application, and they earn interest while they wait.","k":"item"},{"t":"Visit, call or write to us.","p":"Contact","u":"contact/","x":"Our office in Mbarara City is open Monday to Saturday. Come in for a chat, call us, or send an enquiry and we will get back to you.","k":"page"},{"t":"Office address","p":"Contact","u":"contact/#contact","x":"P.O. Box 1234, Mbarara City, Uganda","k":"item"},{"t":"Phone","p":"Contact","u":"contact/#contact","x":"+256 7XX XXX XXX","k":"item"},{"t":"Email","p":"Contact","u":"contact/#contact","x":"info@uawfsacco.co.ug","k":"item"},{"t":"Office hours","p":"Contact","u":"contact/#contact","x":"Mon to Fri: 8:30am to 5:00pm Sat: 9:00am to 1:00pm","k":"item"},{"t":"Send us an enquiry","p":"Contact","u":"contact/#enquiryForm","x":"","k":"item"},{"t":"Frequently asked questions.","p":"FAQ","u":"faq/","x":"Straight answers about how the SACCO works, joining, saving and borrowing. If your question is not here, our office will be glad to help.","k":"page"},{"t":"About the SACCO","p":"FAQ","u":"faq/#questions","x":"Call or visit our office in Mbarara City, or send us a message.","k":"section"},{"t":"Still have a question?","p":"FAQ","u":"faq/#questions","x":"Call or visit our office in Mbarara City, or send us a message.","k":"item"},{"t":"What is a SACCO?","p":"FAQ","u":"faq/#q-what-is-a-sacco","x":"A SACCO (Savings and Credit Cooperative) is an organisation owned by its members. Members save together, and those savings are lent back out to members as affordable loans. Any profit made benefits the members, not outside owners.","k":"faq"},{"t":"Is my money safe?","p":"FAQ","u":"faq/#q-is-my-money-safe","x":"UAWF SACCO is legally registered under the Cooperative Societies Act, Cap 107, and supervised by the Registrar of Cooperative Societies. We keep proper records and report to our members at every general meeting.","k":"faq"},{"t":"Who runs the SACCO?","p":"FAQ","u":"faq/#q-who-runs-the-sacco","x":"The members do. The general meeting of all members is the highest authority. Members elect a Board of Directors and committees to oversee the SACCO, and staff run the office day to day. You can read more on our About page .","k":"faq"},{"t":"What does “probationary registration” mean?","p":"FAQ","u":"faq/#q-what-does-ldquo-probationary-registration-rdquo-","x":"It is the normal first stage for every newly registered cooperative in Uganda: a two year period in which the Registrar confirms the society is run properly, before full registration. It does not mean the SACCO is temporary.","k":"faq"},{"t":"Who can join?","p":"FAQ","u":"faq/#q-who-can-join","x":"Smallholder farmers, livestock keepers, farm, plantation and dairy workers, agro processing workers and farmer groups. Any Ugandan aged 18 and above can join.","k":"faq"},{"t":"Can people who are not farmers join?","p":"FAQ","u":"faq/#q-can-people-who-are-not-farmers-join","x":"Yes. While we are built around farming, any Ugandan aged 18 and above can join, including agro processing and dairy workers.","k":"faq"},{"t":"What do I need to bring to join?","p":"FAQ","u":"faq/#q-what-do-i-need-to-bring-to-join","x":"Your National ID, two passport size photos, your next of kin details and, if requested, an LC1 letter. You will also pay a one-time entrance fee and buy shares. See the Membership page for the steps.","k":"faq"},{"t":"How much are the entrance fee and shares?","p":"FAQ","u":"faq/#q-how-much-are-the-entrance-fee-and-shares","x":"The amounts are set by members at the general meeting and can change, so please ask our office for the current figures before you come.","k":"faq"},{"t":"How often do I need to save?","p":"FAQ","u":"faq/#q-how-often-do-i-need-to-save","x":"Weekly or monthly, whichever suits your income. What matters most is saving regularly, because your savings history supports your loan applications.","k":"faq"},{"t":"Can I take out my savings?","p":"FAQ","u":"faq/#q-can-i-take-out-my-savings","x":"Savings can be withdrawn according to the SACCO’s savings policy. Shares work differently: they make you an owner and are generally kept while you remain a member. Our office will explain the rules that apply to your account.","k":"faq"},{"t":"Can a farmer group save together?","p":"FAQ","u":"faq/#q-can-a-farmer-group-save-together","x":"Yes. Farmer groups and workers’ associations can open one shared, transparent account and save and borrow together. See group accounts .","k":"faq"},{"t":"Do I need a land title to borrow?","p":"FAQ","u":"faq/#q-do-i-need-a-land-title-to-borrow","x":"No. Most of our loans do not require a land title. We look at your savings history, your group or guarantors, and your farming or business plan.","k":"faq"},{"t":"How much can I borrow?","p":"FAQ","u":"faq/#q-how-much-can-i-borrow","x":"How much you can borrow depends on your savings, your loan type and your ability to repay. Visit the office and our staff will guide you through the amount that fits your situation. You can also try the loan calculator .","k":"faq"},{"t":"Can I repay after harvest?","p":"FAQ","u":"faq/#q-can-i-repay-after-harvest","x":"Yes. Farm input loans are designed to be repaid after you harvest and sell your produce. We agree a repayment plan with you before you borrow.","k":"faq"},{"t":"What is a guarantor?","p":"FAQ","u":"faq/#q-what-is-a-guarantor","x":"A guarantor is usually a fellow member who knows you and agrees to support your loan. If a borrower cannot repay, guarantors share responsibility, which is why members guarantee each other carefully.","k":"faq"},{"t":"What if I struggle to repay on time?","p":"FAQ","u":"faq/#q-what-if-i-struggle-to-repay-on-time","x":"Talk to our office as early as you can. Farming has good and hard seasons, and it is always better to discuss your situation before a payment is missed.","k":"faq"},{"t":"Savings and Credit for The People who grow Our Food.","p":"Home","u":"./","x":"Save a little, regularly, and borrow fairly for seed, livestock and your family. Built for farmers, livestock keepers and agricultural workers around Mbarara City.","k":"page"},{"t":"Become a member and an owner.","p":"Membership","u":"membership/","x":"Joining UAWF SACCO takes four simple steps. Once you are a member, you own a share of the SACCO, you can save and borrow, and you have a vote.","k":"page"},{"t":"Four simple steps","p":"Membership","u":"membership/#how-to-join","x":"You can start at our office in Mbarara City. Our staff will guide you through each step.","k":"section"},{"t":"Visit or contact the office","p":"Membership","u":"membership/#how-to-join","x":"Come to our office in Mbarara City, or call us, to learn more and ask questions.","k":"item"},{"t":"Fill the application form","p":"Membership","u":"membership/#how-to-join","x":"Complete a short membership form with your basic details.","k":"item"},{"t":"Pay entrance fee & buy shares","p":"Membership","u":"membership/#how-to-join","x":"A single entrance fee and a small number of shares make you an owner of the SACCO.","k":"item"},{"t":"Start saving","p":"Membership","u":"membership/#how-to-join","x":"Begin your regular savings, weekly or monthly, whatever suits your income.","k":"item"},{"t":"Who can join, and what to bring","p":"Membership","u":"membership/#requirements","x":"","k":"section"},{"t":"Who can join","p":"Membership","u":"membership/#requirements","x":"Smallholder farmers Livestock keepers Farm, plantation and dairy workers Agro processing workers Farmer groups and associations Any Ugandan aged 18 years and above","k":"item"},{"t":"What to bring","p":"Membership","u":"membership/#requirements","x":"National ID Two passport size photos Next of kin details LC1 letter (if requested)","k":"item"},{"t":"What membership gives you","p":"Membership","u":"membership/#benefits","x":"A SACCO is owned by its members. That means the benefits stay with the people who save and borrow here.","k":"section"},{"t":"A safe place to save","p":"Membership","u":"membership/#benefits","x":"Your savings are kept with clear records in a society registered and supervised by the Registrar.","k":"item"},{"t":"Loans that suit farming","p":"Membership","u":"membership/#benefits","x":"Borrow for inputs, livestock or emergencies, with repayment that follows your season.","k":"item"},{"t":"You own a share","p":"Membership","u":"membership/#benefits","x":"Your shares make you a part owner. Any surplus benefits members, as agreed at the general meeting.","k":"item"},{"t":"A vote that counts","p":"Membership","u":"membership/#benefits","x":"One member, one vote. Elect the board and committees and help set SACCO policy.","k":"item"},{"t":"Free training","p":"Membership","u":"membership/#benefits","x":"Sessions on financial literacy, record keeping, good farming practice and markets.","k":"item"},{"t":"A community behind you","p":"Membership","u":"membership/#benefits","x":"Fellow members who support each other through good seasons and hard ones.","k":"item"},{"t":"Entrance fee and shares","p":"Membership","u":"membership/#fees","x":"New members pay a one-time entrance fee and buy a small number of shares. The current amounts are set by members at the general meeting, so please ask our office for the latest figures before you come.","k":"section"},{"t":"Products built around farm life.","p":"Services","u":"services/","x":"Simple savings and fair credit that work with your harvest, your herd and your household, plus free training to help your farm grow.","k":"page"},{"t":"Savings that grow with you","p":"Services","u":"services/#savings-section","x":"Saving regularly keeps your money safe, earns you interest and builds the record you need to borrow.","k":"section"},{"t":"Regular savings","p":"Services","u":"services/#savings","x":"Save weekly or monthly, any amount you can manage. Your savings are kept safely with clear records, and they grow over time. Save on a schedule that suits your income Builds your savings history for future loans Clear statements of what you have saved","k":"item"},{"t":"Group savings & loans","p":"Services","u":"services/#group-accounts","x":"Farmer groups and workers’ associations can save and borrow together, with one shared, transparent account the whole group can follow. One account for the whole group Members support and guarantee each other Open records the group can check at any time","k":"item"},{"t":"Loans that follow the season","p":"Services","u":"services/#loans","x":"Fair credit for farming and family life, with repayment plans agreed with you before you borrow.","k":"section"},{"t":"Farm input loans","p":"Services","u":"services/#input-loans","x":"Borrow for seed, fertiliser, feed or tools, and repay after you harvest or sell. Sized to fit your garden or plantation. Seed, fertiliser, feed and tools Repay after harvest or sale Most do not need a land title","k":"item"},{"t":"Development loans","p":"Services","u":"services/#development-loans","x":"Bigger goals need bigger support: a dairy cow, a water tank, a storage store, or a small agribusiness of your own. Livestock, water and storage Starting or growing an agribusiness Longer repayment periods","k":"item"},{"t":"Emergency loans","p":"Services","u":"services/#emergency-loans","x":"Quick help for the moments you cannot plan for, like school fees due tomorrow or a sudden medical bill. School fees and medical bills Processed quickly Short, simple repayment","k":"item"},{"t":"Free training for members","p":"Services","u":"services/#training","x":"Practical sessions that help you manage money well and get more from your farm.","k":"section"},{"t":"Financial literacy","p":"Services","u":"services/#training","x":"Budgeting, saving and borrowing wisely.","k":"item"},{"t":"Record keeping","p":"Services","u":"services/#training","x":"Simple farm and business records.","k":"item"},{"t":"Good farming practice","p":"Services","u":"services/#training","x":"Better yields from your land and herd.","k":"item"},{"t":"Better markets","p":"Services","u":"services/#training","x":"Finding fair buyers for your produce.","k":"item"},{"t":"Getting a loan, step by step","p":"Services","u":"services/#apply","x":"Loans are for members. Here is what the process looks like once you have joined and started saving.","k":"section"},{"t":"Be an active member","p":"Services","u":"services/#apply","x":"Join the SACCO, buy your shares and save regularly. Your savings history supports your loan.","k":"item"},{"t":"Talk to our office","p":"Services","u":"services/#apply","x":"Tell us what you need the loan for. We will explain the options and what you need to bring.","k":"item"},{"t":"Apply with guarantors","p":"Services","u":"services/#apply","x":"Fill the loan form with your plan and your guarantors, usually fellow members who know you.","k":"item"},{"t":"Review and repayment plan","p":"Services","u":"services/#apply","x":"The Credit Committee reviews your application, and we agree a repayment plan that fits your season.","k":"item"},{"t":"See what a loan could cost you","p":"Services","u":"services/#services-cta","x":"Try the loan calculator for an estimated monthly repayment, then talk to our office about the loan that fits you.","k":"section"}];